CREATE TABLE "backup_log" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "ts" INTEGER NOT NULL, "uri" TEXT NULL, "bytes" INTEGER NOT NULL DEFAULT 0, "ok" INTEGER NOT NULL CHECK ("ok" IN (0, 1)), "error" TEXT NULL);
CREATE TABLE "card" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "note_id" INTEGER NOT NULL REFERENCES note (id), "ord" INTEGER NOT NULL DEFAULT 0, "state" TEXT NOT NULL DEFAULT 'new', "step" INTEGER NOT NULL DEFAULT 0, "due" INTEGER NOT NULL, "stability" REAL NULL, "difficulty" REAL NULL, "reps" INTEGER NOT NULL DEFAULT 0, "lapses" INTEGER NOT NULL DEFAULT 0, "last_review" INTEGER NULL, "suspended" INTEGER NOT NULL DEFAULT 0 CHECK ("suspended" IN (0, 1)), "buried_until" INTEGER NULL);
CREATE TABLE "domain" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL UNIQUE, "active" INTEGER NOT NULL DEFAULT 1 CHECK ("active" IN (0, 1)), "created_at" INTEGER NOT NULL);
CREATE TABLE "engine_decision" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "ts" INTEGER NOT NULL, "engine_version" TEXT NOT NULL, "seed" INTEGER NOT NULL, "features_json" TEXT NOT NULL, "scores_json" TEXT NOT NULL, "chosen_json" TEXT NOT NULL);
CREATE TABLE "fsrs_params" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" INTEGER NOT NULL, "version" TEXT NOT NULL, "params_json" TEXT NOT NULL, "desired_retention" REAL NOT NULL);
CREATE TABLE "interest_log" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "ts" INTEGER NOT NULL, "domain_id" INTEGER NOT NULL REFERENCES domain (id), "value" INTEGER NOT NULL);
CREATE TABLE "note" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "guid" TEXT NOT NULL UNIQUE, "domain_id" INTEGER NOT NULL REFERENCES domain (id), "syllabus_item_id" INTEGER NULL REFERENCES syllabus_item (id), "type" TEXT NOT NULL, "fields_json" TEXT NOT NULL, "tags" TEXT NOT NULL DEFAULT '', "source_type" TEXT NULL, "source_ref" TEXT NULL, "llm_confidence" TEXT NULL, "created_at" INTEGER NOT NULL);
CREATE TABLE "prompt_log" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" INTEGER NOT NULL, "domain_id" INTEGER NOT NULL REFERENCES domain (id), "syllabus_item_id" INTEGER NULL REFERENCES syllabus_item (id), "template_version" TEXT NOT NULL, "prompt_text" TEXT NOT NULL, "cards_requested" INTEGER NOT NULL, "cards_imported" INTEGER NOT NULL DEFAULT 0, "status" TEXT NOT NULL DEFAULT 'issued');
CREATE TABLE "review_log" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "card_id" INTEGER NOT NULL REFERENCES card (id), "reviewed_at" INTEGER NOT NULL, "rating" INTEGER NOT NULL, "duration_ms" INTEGER NOT NULL DEFAULT 0, "state_before" TEXT NOT NULL, "due_before" INTEGER NOT NULL, "stability_before" REAL NULL, "difficulty_before" REAL NULL, "elapsed_days" REAL NOT NULL, "scheduled_days" REAL NOT NULL, "fsrs_version" TEXT NOT NULL, "params_id" INTEGER NOT NULL REFERENCES fsrs_params (id), "revoked_at" INTEGER NULL);
CREATE TABLE "setting" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "syllabus_item" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "domain_id" INTEGER NOT NULL REFERENCES domain (id), "title" TEXT NOT NULL, "level" INTEGER NOT NULL DEFAULT 1, "position" INTEGER NOT NULL DEFAULT 0, "status" TEXT NOT NULL DEFAULT 'todo');
CREATE INDEX card_due_idx ON card (due);
CREATE INDEX card_note_idx ON card (note_id);
CREATE INDEX review_log_card_idx ON review_log (card_id);
CREATE INDEX review_log_time_idx ON review_log (reviewed_at);